curl -s --connect-timeout 10 --max-time 15 "https://huggingface.co/api/datasets/badlogicgames/pi-mono" 2>/dev/null | python3 -c "
import json, sys
try:
    data = json.load(sys.stdin)
    if 'cardData' in data:
